class JournalsLoader{constructor(){this.loadingStates={impact:!1,representation:!1};const e=document.querySelector('meta[name="ethnos-api-base"]');this.apiBase=(e&&e.content?e.content.trim():"/backend/api").replace(/\/$/,"")}async loadVenuesByImpact(){this.loadingStates.impact=!0;const e=document.querySelector(".venues-impact-container");if(e)try{e.innerHTML='<p class="field-value">Carregando periódicos por impacto...</p>',e.innerHTML='\n                <p class="field-value">\n                    Dados de impacto não disponíveis no momento. \n                    <a href="/venues/complete" class="action-link">Ver listagem completa de periódicos</a>\n                </p>\n            '}catch(n){console.error("Error loading venues by impact:",n),e.innerHTML='<p class="field-value error-text">Erro ao carregar dados de impacto</p>'}finally{this.loadingStates.impact=!1}else console.error("Venues impact container not found")}async loadVenuesByRepresentation(){this.loadingStates.representation=!0;const e=document.querySelector(".venues-representation-container");if(e)try{e.innerHTML='<p class="field-value">Carregando periódicos por representação...</p>';const n=new AbortController,t=setTimeout(()=>n.abort(),1e4),a=await fetch("/venues/complete",{signal:n.signal,headers:{Accept:"text/html"}});if(clearTimeout(t),!a.ok)throw new Error(`HTTP ${a.status}: ${a.statusText}`);const s=[1,917,58,122,1027,47,157,75],o=[];for(const e of s)try{const n=await fetch(`${this.apiBase}/venues/${e}`);if(n.ok){const t=await n.json(),a=t?.data||t?.venue||t;a&&o.push({id:e,name:a.name,type:a.type,works_count:a.works_count})}}catch(n){console.warn(`Failed to fetch venue ${e}:`,n)}let r="";if(o.length>0){o.sort((e,n)=>(n.works_count||0)-(e.works_count||0));r=`\n                    <table class="data-table journals-representation-table">\n                        <thead>\n                            <tr>\n                                <th scope="col">PERIÓDICO</th>\n                                <th scope="col">TIPO</th>\n                                <th scope="col">OBRAS</th>\n                                <th scope="col">AÇÃO</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            ${o.slice(0,5).map(e=>`\n                                <tr>\n                                    <td class="field-value">\n                                        <strong>${e.name||"Nome não disponível"}</strong>\n                                    </td>\n                                    <td class="field-value">\n                                        ${"JOURNAL"===e.type?"Periódico":e.type||"N/A"}\n                                    </td>\n                                    <td class="field-value">\n                                        <strong>${(e.works_count||0).toLocaleString()}</strong>\n                                    </td>\n                                    <td class="field-value">\n                                        <a href="/venues/${e.id}" class="action-link">Ver detalhes</a>\n                                    </td>\n                                </tr>\n                            `).join("")}\n                        </tbody>\n                    </table>\n                `}let l=0;try{const e=await fetch(`${this.apiBase}/venues?limit=1&page=1`);if(e.ok){const n=await e.json();l=n?.pagination?.total||n?.pagination?.totalResults||0}}catch(e){console.warn("Failed to load venues statistics via proxy:",e),l=4856}e.innerHTML=`\n                <div class="venues-preview">\n                    ${r||'\n                        <table class="data-table journals-representation-table">\n                            <thead>\n                                <tr>\n                                    <th scope="col">PERIÓDICO</th>\n                                    <th scope="col">TIPO</th>\n                                    <th scope="col">OBRAS</th>\n                                    <th scope="col">AÇÃO</th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr>\n                                    <td class="field-value">\n                                        <strong>American Anthropologist</strong>\n                                    </td>\n                                    <td class="field-value">Periódico</td>\n                                    <td class="field-value"><strong>31.070</strong></td>\n                                    <td class="field-value">\n                                        <a href="/venues/1" class="action-link">Ver detalhes</a>\n                                    </td>\n                                </tr>\n                                <tr>\n                                    <td class="field-value">\n                                        <strong>Contemporary Sociology</strong>\n                                    </td>\n                                    <td class="field-value">Periódico</td>\n                                    <td class="field-value"><strong>25.882</strong></td>\n                                    <td class="field-value">\n                                        <a href="/venues/917" class="action-link">Ver detalhes</a>\n                                    </td>\n                                </tr>\n                                <tr>\n                                    <td class="field-value">\n                                        <strong>American Journal of Sociology</strong>\n                                    </td>\n                                    <td class="field-value">Periódico</td>\n                                    <td class="field-value"><strong>25.074</strong></td>\n                                    <td class="field-value">\n                                        <a href="/venues/58" class="action-link">Ver detalhes</a>\n                                    </td>\n                                </tr>\n                                <tr>\n                                    <td class="field-value">\n                                        <strong>Social Forces</strong>\n                                    </td>\n                                    <td class="field-value">Periódico</td>\n                                    <td class="field-value"><strong>20.770</strong></td>\n                                    <td class="field-value">\n                                        <a href="/venues/122" class="action-link">Ver detalhes</a>\n                                    </td>\n                                </tr>\n                                <tr>\n                                    <td class="field-value">\n                                        <strong>Annales. Histoire, Sciences Sociales</strong>\n                                    </td>\n                                    <td class="field-value">Periódico</td>\n                                    <td class="field-value"><strong>16.465</strong></td>\n                                    <td class="field-value">\n                                        <a href="/venues/1027" class="action-link">Ver detalhes</a>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    '}\n                    <div class="action-links">\n                        <p class="field-value">\n                            <strong>${l.toLocaleString()} periódicos disponíveis</strong> - \n                            <a href="/venues/complete" class="action-link">Ver todos os periódicos organizados</a> | \n                            <a href="/search/advanced" class="action-link">Busca avançada</a>\n                        </p>\n                    </div>\n                </div>\n            `}catch(n){console.error("Error loading venues by representation:",n),"AbortError"===n.name||n.message.includes("timeout")?e.innerHTML='\n                    <p class="field-value error-text">\n                        Timeout ao carregar periódicos. A base de dados é muito grande.\n                        <br><a href="/venues/complete" class="action-link">Ver listagem completa de periódicos</a>\n                        <br><a href="/search/advanced" class="action-link">Ou use a busca avançada para filtros específicos</a>\n                    </p>\n                ':e.innerHTML='\n                    <p class="field-value error-text">\n                        Erro ao carregar periódicos. \n                        <br><a href="/venues/complete" class="action-link">Ver listagem completa</a>\n                    </p>\n                '}finally{this.loadingStates.representation=!1}else console.error("Venues representation container not found")}async init(){try{await Promise.all([this.loadVenuesByImpact(),this.loadVenuesByRepresentation()])}catch(e){console.error("Error initializing journals loader:",e)}}}document.addEventListener("DOMContentLoaded",function(){(new JournalsLoader).init()});